  7→    inline __device__ void operator()(scalar *address, scalar val) {           \
  8→      uint32_t *address_as_ui = (uint32_t *)(address - ((size_t)address & 3)); \
  9→      uint32_t old = *address_as_ui;                                           \
 10→      uint32_t shift = ((size_t)address & 3) * 8;                              \
 11→      uint32_t sum;                                                            \
 12→      uint32_t assumed;                                                        \
 13→                                                                               \
 14→      do {                                                                     \
