  9→
 10→#define THREADS 256
 11→#define BLOCKS(N) (N + THREADS - 1) / THREADS
 12→
 13→template <typename scalar_t, ReductionType REDUCE>
 14→__global__ void
 15→scatter_kernel(const scalar_t *src_data,
 16→               const at::cuda::detail::TensorInfo<int64_t, int> index_info,
 17→               scalar_t *out_data, int E, int K, int N, int numel) {
 18→
 19→  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
 20→
 21→  int b = thread_idx / (E * K);
 22→  int k = thread_idx % K;
 23→
 24→  if (thread_idx < numel) {
 25→    int offset = at::cuda::detail::IndexToOffset<int64_t, int, -1>::get(
 26→        thread_idx, index_info);
 27→    int64_t idx = index_info.data[offset];
 28→
 29→    Reducer<scalar_t, REDUCE>::atomic_write(out_data + b * N * K + idx * K + k,
 30→                                            src_data[thread_idx]);
 31→  }
 32→}
 33→
 34→template <typename scalar_t>
 35→__global__ void
 36→scatter_arg_kernel(const scalar_t *src_data,
 37→                   const at::cuda::detail::TensorInfo<int64_t, int> index_info,
 38→                   const scalar_t *out_data, int64_t *arg_out_data, int E,
 39→                   int K, int N, int numel) {
 40→
 41→  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
 42→
 43→  int b = thread_idx / (E * K);
 44→  int e = (thread_idx / K) % E;
 45→  int k = thread_idx % K;
 46→
 47→  if (thread_idx < numel) {
 48→    int offset = at::cuda::detail::IndexToOffset<int64_t, int, -1>::get(
 49→        thread_idx, index_info);
 50→    int64_t idx = index_info.data[offset];
 51→
 52→    if (src_data[thread_idx] == out_data[b * N * K + idx * K + k]) {
 53→      arg_out_data[b * N * K + idx * K + k] = e;
 54→    }
 55→  }
 56→}
