 58→std::tuple<torch::Tensor, std::optional<torch::Tensor>>
 59→scatter_cuda(torch::Tensor src, torch::Tensor index, int64_t dim,
 60→             std::optional<torch::Tensor> optional_out,
 61→             std::optional<int64_t> dim_size, std::string reduce) {
 62→  CHECK_CUDA(src);
 63→  CHECK_CUDA(index);
 64→  if (optional_out.has_value())
 65→    CHECK_CUDA(optional_out.value());
 66→  c10::cuda::MaybeSetDevice(src.get_device());
 67→
 68→  CHECK_INPUT(src.dim() == index.dim());
 69→  for (auto i = 0; i < index.dim() - 1; i++)
 70→    CHECK_INPUT(src.size(i) >= index.size(i));
 71→
 72→  src = src.contiguous();
 73→
 74→  torch::Tensor out;
 75→  if (optional_out.has_value()) {
 76→    out = optional_out.value().contiguous();
 77→    for (auto i = 0; i < out.dim(); i++)
 78→      if (i != dim)
 79→        CHECK_INPUT(src.size(i) == out.size(i));
 80→  } else {
 81→    auto sizes = src.sizes().vec();
 82→    if (dim_size.has_value())
 83→      sizes[dim] = dim_size.value();
 84→    else if (index.numel() == 0)
 85→      sizes[dim] = 0;
 86→    else {
 87→      sizes[dim] = 1 + index.max().cpu().data_ptr<int64_t>()[0];
 88→    }
 89→    out = torch::empty(sizes, src.options());
 90→  }
 91→
 92→  std::optional<torch::Tensor> arg_out = std::nullopt;
 93→  int64_t *arg_out_data = nullptr;
 94→  if (reduce2REDUCE.at(reduce) == MIN || reduce2REDUCE.at(reduce) == MAX) {
 95→    arg_out = torch::full_like(out, src.size(dim), index.options());
 96→    arg_out_data = arg_out.value().data_ptr<int64_t>();
 97→  }
 98→
 99→  if (src.numel() == 0) {
100→    if (!optional_out.has_value())
101→      out.fill_(0);
102→    return std::make_tuple(out, arg_out);
103→  }
104→
105→  auto B = 1;
106→  for (auto i = 0; i < dim; i++)
107→    B *= src.size(i);
108→  auto E = src.size(dim);
109→  auto K = src.numel() / (B * E);
110→  auto N = out.size(dim);
111→
112→  auto index_info = at::cuda::detail::getTensorInfo<int64_t, int>(index);
113→  auto stream = at::cuda::getCurrentCUDAStream();
114→  AT_DISPATCH_ALL_TYPES_AND2(at::ScalarType::Half, at::ScalarType::BFloat16, src.scalar_type(), "_", [&] {
115→    auto src_data = src.data_ptr<scalar_t>();
116→    auto out_data = out.data_ptr<scalar_t>();
117→
118→    AT_DISPATCH_REDUCTION_TYPES(reduce, [&] {
119→      if (!optional_out.has_value())
120→        out.fill_(Reducer<scalar_t, REDUCE>::init());
121→
122→      scatter_kernel<scalar_t, REDUCE>
123→          <<<BLOCKS(src.numel()), THREADS, 0, stream>>>(
124→              src_data, index_info, out_data, E, K, N, src.numel());
125→
126→      if (!optional_out.has_value() && (REDUCE == MIN || REDUCE == MAX))
127→        out.masked_fill_(out == Reducer<scalar_t, REDUCE>::init(), (scalar_t)0);
128→
129→      if (REDUCE == MIN || REDUCE == MAX)
130→        scatter_arg_kernel<scalar_t>
131→            <<<BLOCKS(src.numel()), THREADS, 0, stream>>>(
132→                src_data, index_info, out_data, arg_out_data, E, K, N,
133→                src.numel());
134→    });
135→  });
136→
137→  return std::make_tuple(out, arg_out);
138→}
