144→    int out_idx = ((row_idx / D) * N + idx) * K + col_idx;
145→
146→    scalar_t val = __ldg(out_data + out_idx);
147→    if (src_data[thread_idx] == val)
148→      arg_out_data[out_idx] = row_idx % D;
149→  }
