 18→                   const at::cuda::detail::TensorInfo<int64_t, int> indptr_info,
 19→                   scalar_t *out_data, int64_t *arg_out_data, size_t N,
 20→                   size_t E) {
 21→
 22→  // Each warp processes exactly `32/TB` rows and aggregates all row values
 23→  // via a parallel reduction.
 24→
 25→  int thread_idx = blockIdx.x * blockDim.x + threadIdx.x;
 26→  int row_idx = thread_idx / TB;
 27→  int lane_idx = thread_idx & (TB - 1);
 28→
 29→  if (row_idx < N) {
 30→    int offset = IndexPtrToOffset<int64_t>::get(row_idx, indptr_info);
 31→    int64_t row_start = __ldg(indptr_info.data + offset);
 32→    int64_t row_end = __ldg(indptr_info.data + offset +
 33→                            indptr_info.strides[indptr_info.dims - 1]);
 34→
 35→    scalar_t val = Reducer<scalar_t, REDUCE>::init();
 36→    int64_t arg, arg_tmp;
 37→
 38→    offset = (row_idx / (indptr_info.sizes[indptr_info.dims - 1] - 1)) * E;
 39→    for (int64_t src_idx = row_start + lane_idx; src_idx < row_end;
 40→         src_idx += TB) {
 41→      Reducer<scalar_t, REDUCE>::update(&val, src_data[offset + src_idx], &arg,
 42→                                        src_idx);
 43→    }
 44→
 45→#pragma unroll
 46→    for (int i = TB / 2; i > 0; i /= 2) {
 47→      // Parallel reduction inside a single warp.
 48→      if (REDUCE == MIN || REDUCE == MAX)
 49→        arg_tmp = SHFL_DOWN_SYNC(FULL_MASK, arg, i);
 50→      Reducer<scalar_t, REDUCE>::update(
 51→          &val, SHFL_DOWN_SYNC(FULL_MASK, val, i), &arg, arg_tmp);
 52→    }
 53→
 54→    if (lane_idx == 0) {
 55→      Reducer<scalar_t, REDUCE>::write(out_data + row_idx, val,
 56→                                       arg_out_data + row_idx, arg,
 57→                                       row_end - row_start);
 58→    }
 59→  }
